function slug(value){return value.toLowerCase().replace(/\s+/g,"-")}
function escapeHtml(value){const div=document.createElement("div");div.textContent=String(value);return div.innerHTML}
function showStage(stage){$("#accessGate").hidden=stage!=="gate";$("#onboarding").hidden=stage!=="onboarding";$("#appShell").hidden=stage!=="app"}
function toast(message){const node=$("#toast");node.textContent=message;node.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.hidden=true,2600)}

$("#accessForm").addEventListener("submit",event=>{event.preventDefault();const code=new FormData(event.currentTarget).get("accessCode").trim().toUpperCase().replace(/[-\s]/g,"");if(!ROLE_CODES[code]){$("#accessMessage").textContent="That code was not recognised. Check it and try again.";$("#accessMessage").classList.add("error");return}pendingRole=ROLE_CODES[code];$("#assignedRole").textContent=pendingRole==="admin"?"Admin":pendingRole==="media"?"Media person":"Normal user";showStage("onboarding")});
$("#backToCode").addEventListener("click",()=>showStage("gate"));
async function registerProfile(profile){const response=await fetch("/api/users/",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(profile)});const payload=await response.json();if(!response.ok)throw new Error(payload.error||"Could not save this user");return payload.user}
$("#profileForm").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),button=form.querySelector('button[type="submit"]');button.disabled=true;try{const profile=await registerProfile({name:data.get("fullName").trim(),phone:data.get("phone").trim(),role:pendingRole});localStorage.setItem("oaTeamsProfile",JSON.stringify(profile));applyProfile(profile);showStage("app")}catch(error){toast(error.message)}finally{button.disabled=false}});

function roleLabel(role){return role==="admin"?"Admin":role==="media"?"Media person":"Normal user"}
function applyProfile(profile){activeRole=profile.role;const initials=profile.name.split(/\s+/).slice(0,2).map(word=>word[0]).join("").toUpperCase()||"TM";$("#profileName").textContent=profile.name;$("#profileInitials").textContent=initials;$("#profileRole").textContent=roleLabel(activeRole);$("#currentMemberName").textContent=profile.name;$("#currentMemberAvatar").textContent=initials;$("#currentMemberRole").textContent=roleLabel(activeRole);applyRoleVisibility(activeRole)}
function applyRoleVisibility(role){const isAdmin=role==="admin",isMedia=role==="media";$("#accessNav").hidden=!isAdmin;$$(`.admin-action`).forEach(node=>node.hidden=!isAdmin);$$("#primaryNav button[data-view]").forEach(button=>button.hidden=isMedia&&button.dataset.view!=="media");if(isMedia)openView("media");else if(!isAdmin&&$("#accessView").classList.contains("active"))openView("tasks");renderTasks();syncMedia()}
function openView(name){$$('[data-view-panel]').forEach(panel=>{panel.classList.toggle("active",panel.dataset.viewPanel===name);panel.hidden=panel.dataset.viewPanel!==name});$$('#primaryNav button').forEach(button=>button.classList.toggle("active",button.dataset.view===name));const titles={tasks:"Activities",media:"Media and Documents",tributes:"Tributes",access:"Access control"};$("#viewTitle").textContent=titles[name];$("#sidebar").classList.remove("open");$("#menuButton").setAttribute("aria-expanded","false");window.scrollTo({top:0,behavior:"smooth"})}
$("#primaryNav").addEventListener("click",event=>{const button=event.target.closest("button[data-view]");if(button&&!button.hidden)openView(button.dataset.view)});
$("#menuButton").addEventListener("click",()=>{const open=$("#sidebar").classList.toggle("open");$("#menuButton").setAttribute("aria-expanded",String(open))});
$("#signOut").addEventListener("click",()=>{localStorage.removeItem("oaTeamsProfile");location.reload()});

function visibleTasks(){const query=$("#taskSearch").value.trim().toLowerCase(),status=$("#taskStatusFilter").value;return tasks.filter(item=>(selectedCommittee==="all"||item.mainCommittee===selectedCommittee)&&(selectedSubcommittee==="all"||item.subcommitteeId===selectedSubcommittee)&&(status==="all"||item.status===status)&&`${item.task} ${item.owner} ${item.subcommittee} ${(item.supportingMembers||[]).join(" ")} ${(item.labels||[]).join(" ")}`.toLowerCase().includes(query))}
function renderStats(){const scope=tasks.filter(t=>selectedCommittee==="all"||t.mainCommittee===selectedCommittee),today=new Date().toISOString().slice(0,10);const counts={total:scope.length,completed:scope.filter(t=>t.status==="completed").length,progress:scope.filter(t=>["in-progress","nearing-completion"].includes(t.status)).length,overdue:scope.filter(t=>t.deadline&&t.deadline<today&&t.status!=="completed").length};$("#taskStats").innerHTML=`<article><span>Total activities</span><strong>${counts.total}</strong><small>In the selected committee</small></article><article><span>In progress</span><strong>${counts.progress}</strong><small>Currently being worked on</small></article><article><span>Completed</span><strong>${counts.completed}</strong><small>Recorded in the plan</small></article><article><span>Past deadline</span><strong>${counts.overdue}</strong><small>Needs an update</small></article>`;const received=tributeParties.filter(p=>p.tribute==="Received").length,sent=tributeParties.filter(p=>p.request==="Sent").length,supporting=tributeParties.reduce((sum,p)=>sum+p.files.filter(file=>file.type!=="tribute").length,0),tributes=tributeParties.reduce((sum,p)=>sum+p.files.filter(file=>file.type==="tribute").length,0);$("#tributeStats").innerHTML=`<article><span>Interested parties</span><strong>${tributeParties.length}</strong><small>From the source register</small></article><article><span>Requests sent</span><strong>${sent}</strong><small>${tributeParties.length-sent} still to send</small></article><article><span>Tributes received</span><strong>${received}</strong><small>${tributeParties.length-received} outstanding</small></article><article><span>Uploaded documents</span><strong>${supporting+tributes}</strong><small>${supporting} supporting · ${tributes} tributes</small></article>`}

function renderCalendar(){const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth();$("#calendarTitle").textContent=new Intl.DateTimeFormat("en-GH",{month:"long",year:"numeric"}).format(calendarMonth);const first=new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(year,month,1-offset);const weekdays=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];let html=weekdays.map(day=>`<div class="calendar-weekday">${day}</div>`).join("");for(let index=0;index<42;index++){const date=new Date(start);date.setDate(start.getDate()+index);const iso=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;const items=[...tasks.filter(t=>t.deadline===iso).map(t=>({id:t.id,title:t.task,type:"task"})),...funeralEvents.filter(e=>e.date===iso)];const today=new Date(),isToday=date.toDateString()===today.toDateString();html+=`<div class="calendar-day ${date.getMonth()!==month?"outside":""} ${isToday?"today":""}"><span class="day-number">${date.getDate()}</span>${items.slice(0,3).map(item=>item.id?`<div class="calendar-event-row"><button class="calendar-event ${item.type}" data-calendar-task="${item.id}" title="Open ${escapeHtml(item.title)}">${escapeHtml(item.title)}</button><button class="calendar-share" data-share-task="${item.id}" type="button" aria-label="Share ${escapeHtml(item.title)} on WhatsApp" title="Share on WhatsApp">W</button></div>`:`<button class="calendar-event ${item.type}" title="${escapeHtml(item.title)}">${escapeHtml(item.title)}</button>`).join("")}${items.length>3?`<small>+${items.length-3} more</small>`:""}</div>`}$("#calendar").innerHTML=html}
$("#calendarPrev").addEventListener("click",()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);renderCalendar()});
$("#calendarNext").addEventListener("click",()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);renderCalendar()});
$("#calendarToday").addEventListener("click",()=>{calendarMonth=new Date();calendarMonth.setDate(1);renderCalendar()});
$("#calendar").addEventListener("click",event=>{const share=event.target.closest("[data-share-task]");if(share){shareTask(tasks.find(item=>item.id===Number(share.dataset.shareTask)));return}const button=event.target.closest("[data-calendar-task]");if(!button)return;const task=tasks.find(item=>item.id===Number(button.dataset.calendarTask));openModal("task",task,activeRole!=="admin")});

function statusText(value){return value.split("-").map(word=>word[0].toUpperCase()+word.slice(1)).join(" ")}
function committeeLabel(value){return {funeral:"Funeral Committee",brochure:"Brochure Committee",oko:"Logistics Uncle Oko"}[value]||value}
function formatDate(value){return value?new Intl.DateTimeFormat("en-GH",{day:"numeric",month:"short",year:"numeric"}).format(new Date(value+"T12:00:00")):"Not set"}
function taskMessage(task){return `*Oko and Atteh - Activity*\n\n*${task.task}*\nCommittee: ${committeeLabel(task.mainCommittee)}\nSubcommittee: ${task.subcommittee}\nPerson responsible: ${task.owner||"To be assigned"}\nDeadline: ${formatDate(task.deadline)}\nPriority: ${task.priority}\nStatus: ${statusText(task.status)}\nProgress: ${task.progress}%${task.notes?`\nNotes: ${task.notes}`:""}`}
function shareTask(task){if(!task)return;window.open(`https://wa.me/?text=${encodeURIComponent(taskMessage(task))}`,"_blank","noopener,noreferrer")}
function sortTasks(records){const mode=$("#taskSort").value,priority={Urgent:0,High:1,Normal:2};return [...records].sort((a,b)=>mode==="progress"?b.progress-a.progress:mode==="updated"?b.updatedAt.localeCompare(a.updatedAt):mode==="priority"?priority[a.priority]-priority[b.priority]:(a.deadline||"9999").localeCompare(b.deadline||"9999"))}
function taskRow(item,isAdmin){const files=(item.attachments||[]).map(file=>`<span class="activity-file"><a href="${file.href}">${escapeHtml(file.name)}</a>${isAdmin?`<button data-remove-activity-file="${file.id}" aria-label="Remove ${escapeHtml(file.name)}">×</button>`:""}</span>`).join("")||"<small>No files</small>";return `<tr><td>${escapeHtml(item.task)}${item.labels?.length?`<small>${item.labels.map(escapeHtml).join(" · ")}</small>`:""}</td><td>${escapeHtml(committeeLabel(item.mainCommittee))}</td><td><span class="subcommittee-pill" style="--group-color:${item.color}">${escapeHtml(item.subcommittee)}</span></td><td>${escapeHtml(item.owner||"To be assigned")}</td><td>${escapeHtml((item.supportingMembers||[]).join(", ")||"—")}</td><td>${formatDate(item.startDate)}</td><td>${formatDate(item.deadline)}</td><td><span class="priority priority-${slug(item.priority)}">${item.priority}</span></td><td><span class="status status-${item.status}">${statusText(item.status)}</span></td><td><div class="progress-track"><i style="width:${item.progress}%"></i></div><small>${item.progress}%</small></td><td>${escapeHtml(item.notes||"—")}</td><td>${new Intl.DateTimeFormat("en-GH",{day:"numeric",month:"short"}).format(new Date(item.updatedAt))}</td><td><div class="activity-files">${files}${isAdmin?`<label class="file-add">+ File<input type="file" data-activity-file="${item.id}"></label>`:""}</div></td><td><div class="task-actions"><button class="whatsapp-button" data-share-task="${item.id}">WhatsApp</button>${isAdmin?`<button class="edit-button" data-edit-task="${item.id}">Edit</button><button class="delete-button" data-delete-task="${item.id}">Delete</button>`:""}</div></td></tr>`}
function groupedProgress(item){const progress=Math.max(0,Math.min(100,Number(item.progress)||0)),tone=progress===100?"completed":item.status;return `<span class="group-progress-row"><span class="group-progress group-progress-${tone}" role="progressbar" aria-label="${escapeHtml(statusText(item.status))}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><i style="width:${progress}%"></i></span><strong>${progress}%</strong></span>`}
function renderCommitteeNavigation(){for(const key of ["all","funeral","brochure","oko"]){const records=key==="all"?tasks:tasks.filter(t=>t.mainCommittee===key);$("#"+key+"TaskCount").textContent=records.length;if(key!=="all")$("#"+key+"TaskSummary").textContent=`${records.filter(t=>t.status==="completed").length} completed`}const groups=subcommittees.filter(s=>s.active&&(selectedCommittee==="all"||s.mainCommittee===selectedCommittee)),select=$("#subcommitteeSelect");select.innerHTML=`<option value="all">All subcommittees (${tasks.filter(t=>selectedCommittee==="all"||t.mainCommittee===selectedCommittee).length})</option>`+groups.map(group=>`<option value="${group.id}">${escapeHtml(group.name)} (${tasks.filter(t=>t.subcommitteeId===group.id).length})</option>`).join("");select.value=groups.some(group=>group.id===selectedSubcommittee)?selectedSubcommittee:"all"}
function renderTasks(){const records=sortTasks(visibleTasks()),isAdmin=activeRole==="admin";renderCommitteeNavigation();renderStats();$("#taskTableBody").innerHTML=records.map(item=>taskRow(item,isAdmin)).join("")||`<tr><td colspan="14">No activities match these filters.</td></tr>`;const groupKey=$("#taskGroup").value,grouped=Object.groupBy?Object.groupBy(records,item=>groupKey==="deadline"?(item.deadline||"No deadline"):item[groupKey]||"Unassigned"):records.reduce((all,item)=>{const key=groupKey==="deadline"?(item.deadline||"No deadline"):item[groupKey]||"Unassigned";(all[key]??=[]).push(item);return all},{});$("#groupedActivities").innerHTML=Object.entries(grouped).map(([name,items])=>`<section class="activity-group"><header><strong>${escapeHtml(groupKey==="mainCommittee"?committeeLabel(name):groupKey==="status"?statusText(name):name)}</strong><span>${items.length}</span></header>${items.map(item=>`<button data-edit-task="${item.id}"><span>${escapeHtml(item.task)}</span><span class="group-task-meta"><small>${escapeHtml(item.owner||"To be assigned")} · ${formatDate(item.deadline)}</small>${groupedProgress(item)}</span></button>`).join("")}</section>`).join("")||`<p class="empty-state">No activities match these filters.</p>`;$(".calendar-card").hidden=activityView!=="calendar";$(".table-card").hidden=activityView==="calendar";$("#activityTableWrap").hidden=activityView==="grouped";$("#groupedActivities").hidden=activityView!=="grouped"}
async function syncActivities(){try{const [taskData,groupData]=await Promise.all([apiJson("/api/activities"),apiJson("/api/activities/subcommittees")]);tasks.splice(0,tasks.length,...taskData.tasks);subcommittees.splice(0,subcommittees.length,...groupData.subcommittees);renderTasks();renderCalendar()}catch(error){console.error("activity_sync_failed",error);toast("Activities could not be loaded.")}}
[$("#taskSearch"),$("#taskStatusFilter"),$("#taskSort"),$("#taskGroup")].forEach(control=>control.addEventListener(control.tagName==="INPUT"?"input":"change",renderTasks));
$("#committeeSelector").addEventListener("click",event=>{const button=event.target.closest("[data-committee]");if(!button)return;selectedCommittee=button.dataset.committee;selectedSubcommittee="all";$$("#committeeSelector button").forEach(item=>item.classList.toggle("active",item===button));renderTasks();renderCalendar()});
$("#subcommitteeSelect").addEventListener("change",event=>{selectedSubcommittee=event.target.value;renderTasks();renderCalendar()});
$("#activityViewTabs").addEventListener("click",event=>{const button=event.target.closest("[data-activity-view]");if(!button)return;activityView=button.dataset.activityView;$$("#activityViewTabs button").forEach(item=>item.classList.toggle("active",item===button));renderTasks()});
function canvasRoundedRect(context,x,y,width,height,radius,fill){context.beginPath();context.roundRect(x,y,width,height,radius);context.fillStyle=fill;context.fill()}
function canvasWrappedLines(context,text,maxWidth,maxLines=2){const words=String(text||"").split(/\s+/),lines=[];let line="";for(const word of words){const candidate=line?`${line} ${word}`:word;if(context.measureText(candidate).width<=maxWidth)line=candidate;else{if(line)lines.push(line);line=word;if(lines.length===maxLines-1)break}}if(line&&lines.length<maxLines)lines.push(line);if(lines.length===maxLines&&words.join(" ")!==lines.join(" ")){while(context.measureText(lines[maxLines-1]+"…").width>maxWidth)lines[maxLines-1]=lines[maxLines-1].slice(0,-1);lines[maxLines-1]+="…"}return lines}
function taskUpdatePool(){const scope=$("#taskUpdateForm").elements.scope.value;return tasks.filter(task=>scope==="all"||task.mainCommittee===scope)}
function populateTaskRange(reset=false){const form=$("#taskUpdateForm"),pool=taskUpdatePool(),start=form.elements.rangeStart,end=form.elements.rangeEnd,oldStart=start.value,oldEnd=end.value;const options=pool.map((task,index)=>`<option value="${index}">${index+1}. ${escapeHtml(task.task)}</option>`).join("");start.innerHTML=options;end.innerHTML=options;if(pool.length){start.value=!reset&&oldStart&&Number(oldStart)<pool.length?oldStart:"0";end.value=!reset&&oldEnd&&Number(oldEnd)<pool.length?oldEnd:String(pool.length-1)}renderTaskUpdate()}
function taskUpdateRecords(){const form=$("#taskUpdateForm"),pool=taskUpdatePool();if(!pool.length)return[];const start=Math.min(Number(form.elements.rangeStart.value)||0,Number(form.elements.rangeEnd.value)||0),end=Math.max(Number(form.elements.rangeStart.value)||0,Number(form.elements.rangeEnd.value)||0);return pool.slice(start,end+1)}
function renderTaskUpdate(){const form=$("#taskUpdateForm"),records=taskUpdateRecords(),canvas=$("#taskUpdateCanvas"),context=canvas.getContext("2d"),width=1080,padding=72,rowHeight=records.length>16?88:104,height=Math.max(1350,500+records.length*rowHeight);canvas.width=width;canvas.height=height;context.fillStyle="#ffffff";context.fillRect(0,0,width,height);const scope=form.elements.scope.value,committee=scope==="all"?"All committees":scope==="funeral"?"Funeral Committee":"Brochure Committee",startIndex=Math.min(Number(form.elements.rangeStart.value)||0,Number(form.elements.rangeEnd.value)||0),endIndex=Math.max(Number(form.elements.rangeStart.value)||0,Number(form.elements.rangeEnd.value)||0),rangeStart=startIndex+1,rangeEnd=endIndex+1;context.fillStyle="#69323a";context.font="800 64px Manrope, sans-serif";context.fillText("Activities update",padding,112);context.fillStyle="#5e5b5c";context.font="500 24px DM Sans, sans-serif";context.fillText(`Dr Isaac Bampoe Addo  |  ${committee}`,padding,158);context.fillStyle="#5e5b5c";context.font="500 19px DM Sans, sans-serif";context.fillText(`Activities ${rangeStart}-${rangeEnd}  |  Prepared ${new Intl.DateTimeFormat("en-GH",{day:"numeric",month:"long",year:"numeric"}).format(new Date())}`,padding,202);context.fillStyle="#69323a";context.font="800 30px Manrope, sans-serif";context.fillText("Selected activities",padding,274);context.fillStyle="#69323a";context.fillRect(padding,302,width-padding*2,62);context.fillStyle="#ffffff";context.font="800 20px DM Sans, sans-serif";context.fillText("No.",padding+18,342);context.fillText("Activity",padding+92,342);context.fillText("Lead / status",width-360,342);let y=364;records.forEach((task,index)=>{context.fillStyle=index%2===0?"#f5f0f1":"#ffffff";context.fillRect(padding,y,width-padding*2,rowHeight);context.strokeStyle="#dfd3d5";context.beginPath();context.moveTo(padding,y+rowHeight);context.lineTo(width-padding,y+rowHeight);context.stroke();context.fillStyle="#171415";context.font="600 19px DM Sans, sans-serif";context.fillText(String(rangeStart+index),padding+20,y+34);context.font="600 20px DM Sans, sans-serif";canvasWrappedLines(context,task.task,555,2).forEach((line,lineIndex)=>context.fillText(line,padding+92,y+33+lineIndex*25));context.fillStyle="#4f4b4c";context.font="500 17px DM Sans, sans-serif";canvasWrappedLines(context,task.owner||"To be assigned",270,1).forEach(line=>context.fillText(line,width-360,y+30));context.fillStyle="#69323a";context.font="800 16px DM Sans, sans-serif";context.fillText(`${statusText(task.status)}  |  ${task.progress}%`,width-360,y+57);context.fillStyle="#6c6869";context.font="500 15px DM Sans, sans-serif";context.fillText(task.deadline?`Due ${formatDate(task.deadline)}`:"No deadline set",width-360,y+80);y+=rowHeight});if(!records.length){context.fillStyle="#6c6869";context.font="600 24px DM Sans, sans-serif";context.fillText("No activities are available for this committee.",padding+24,y+62)}context.strokeStyle="#c9b8bb";context.beginPath();context.moveTo(padding,height-74);context.lineTo(width-padding,height-74);context.stroke();context.fillStyle="#6c6869";context.font="500 16px DM Sans, sans-serif";context.fillText("Dr Isaac Bampoe Addo  |  Activities update",padding,height-42);context.textAlign="right";context.fillText(`${records.length} activities`,width-padding,height-42);context.textAlign="left";$("#taskUpdateRangeSummary").textContent=records.length?`${records.length} activities selected from ${committee}.`:"No activities are available for this committee.";return records.length}
function openTaskUpdate(){const form=$("#taskUpdateForm");form.elements.scope.value=selectedCommittee==="all"?"all":selectedCommittee;populateTaskRange(true);$("#taskUpdateModal").showModal();document.fonts?.ready.then(renderTaskUpdate)}
function downloadTaskUpdate(){const records=renderTaskUpdate();if(!records){toast("Choose a task range before downloading.");return}const canvas=$("#taskUpdateCanvas"),scope=$("#taskUpdateForm").elements.scope.value,filename=`activities-update-${scope}-${new Date().toISOString().slice(0,10)}.jpg`;canvas.toBlob(blob=>{if(!blob){toast("The image could not be created. Please try again.");return}const url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Activities update image downloaded")},"image/jpeg",.95)}
$("#generateTaskUpdate").addEventListener("click",openTaskUpdate);$("#closeTaskUpdate").addEventListener("click",()=>$("#taskUpdateModal").close());$("#regenerateTaskUpdate").addEventListener("click",renderTaskUpdate);$("#downloadTaskUpdate").addEventListener("click",downloadTaskUpdate);$("#taskUpdateForm").elements.scope.addEventListener("change",()=>populateTaskRange(true));$("#taskUpdateForm").elements.rangeStart.addEventListener("change",renderTaskUpdate);$("#taskUpdateForm").elements.rangeEnd.addEventListener("change",renderTaskUpdate);
$("#manageSubcommittees").addEventListener("click",async()=>{const main=selectedCommittee==="all"?"funeral":selectedCommittee,name=prompt(`Add a ${committeeLabel(main)} subcommittee:`);if(!name?.trim())return;try{const payload=await apiJson("/api/activities/subcommittees",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({mainCommittee:main,name:name.trim(),color:"#5679C8"})});subcommittees.push(payload.subcommittee);renderTasks();toast("Subcommittee added")}catch(error){toast(error.message)}});

function statusLabel(value){return {draft:"Draft",review:"Under review",approved:"Approved",archived:"Archived"}[value]||value}
function isVisual(file){return /^image\//.test(file.mimeType||"")}
function formatBytes(bytes){if(!bytes)return "Size unavailable";const units=["B","KB","MB","GB"];const index=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),3);return `${(bytes/1024**index).toFixed(index?1:0)} ${units[index]}`}
function mediaCard(file,isAdmin){const preview=!file.missing&&isVisual(file)?`<img src="${file.previewHref}" alt="${escapeHtml(file.title)}" loading="lazy" onerror="this.closest('.media-preview').classList.add('preview-failed');this.remove()">`:`<span class="document-mark">${file.missing?"!":file.assetType==="media"?"MEDIA":(file.originalName.split(".").pop()||"DOC").toUpperCase()}</span>`;return `<article class="media-card type-${file.assetType}"><div class="media-preview media-${file.assetType} ${isVisual(file)?"":"document-preview"}">${preview}<span class="file-type">${escapeHtml(file.assetType)}</span>${isAdmin?`<span class="availability ${file.available?"available":"private"}">${file.available?"Shared":"Private"}</span>`:""}</div><div class="media-copy"><div class="media-card-heading"><div><h3>${escapeHtml(file.title)}</h3><p>${escapeHtml(file.category)} · ${formatBytes(file.size)}</p></div><span class="media-state ${file.available?"shared":"restricted"}">${statusLabel(file.status)}</span></div><p class="media-description">${escapeHtml(file.description)}</p>${file.labels?.length?`<div class="media-labels">${file.labels.map(label=>`<span>${escapeHtml(label)}</span>`).join("")}</div>`:""}<div class="media-actions">${file.missing?`<span class="file-unavailable">File unavailable</span>`:`<a class="media-view" href="${file.previewHref}" target="_blank" rel="noopener">Preview</a><a href="${file.downloadHref}" download>Download</a>`}${isAdmin?`<button type="button" data-edit-media="${file.id}">Edit</button><button class="media-remove" type="button" data-remove-media="${file.id}">Remove</button><button class="media-access-button" type="button" data-toggle-media="${file.id}">${file.available?"Make private":"Share with media"}</button>`:""}</div></div></article>`}
function renderMedia(){const query=$("#mediaSearch").value.trim().toLowerCase(),filter=$("#mediaFilters .active").dataset.filter,category=$("#mediaCategoryFilter").value,sort=$("#mediaSort").value,isAdmin=activeRole==="admin";let visible=mediaFiles.filter(file=>(filter==="all"||file.assetType===filter)&&(category==="all"||file.category===category)&&`${file.title} ${file.description} ${file.category} ${(file.labels||[]).join(" ")}`.toLowerCase().includes(query));visible.sort((a,b)=>sort==="title"?a.title.localeCompare(b.title):sort==="category"?a.category.localeCompare(b.category):b.uploadedAt.localeCompare(a.uploadedAt));$("#mediaCount").textContent=mediaFiles.length;$("#mediaTypeCount").textContent=mediaFiles.filter(file=>file.assetType==="media").length;$("#documentTypeCount").textContent=mediaFiles.filter(file=>file.assetType==="document").length;$("#mediaSharedCount").textContent=mediaFiles.filter(file=>file.available).length;$("#mediaGrid").innerHTML=visible.map(file=>mediaCard(file,isAdmin)).join("")||`<div class="media-empty"><strong>${mediaFiles.length?"No files match these filters":"No files uploaded"}</strong><span>${mediaFiles.length?"Try another search, category or file type.":"Use Add Media or Document to start the library."}</span></div>`}
function categoryOptions(selected=""){return Object.entries(MEDIA_CATEGORIES).map(([group,items])=>`<optgroup label="${escapeHtml(group)}">${items.map(item=>`<option value="${escapeHtml(item)}"${item===selected?" selected":""}>${escapeHtml(item)}</option>`).join("")}</optgroup>`).join("")}
function refreshCategoryFilter(){const current=$("#mediaCategoryFilter").value;const categories=[...new Set(mediaFiles.map(file=>file.category))].sort();$("#mediaCategoryFilter").innerHTML=`<option value="all">All categories</option>${categories.map(item=>`<option${item===current?" selected":""}>${escapeHtml(item)}</option>`).join("")}`}
async function syncMedia(){$("#mediaLoading").hidden=false;try{const payload=await apiJson("/api/media");mediaFiles.splice(0,mediaFiles.length,...(Array.isArray(payload.items)?payload.items:[]));refreshCategoryFilter();renderMedia()}catch(error){console.error("media_sync_failed",error);$("#mediaGrid").innerHTML=`<div class="media-empty"><strong>Media and Documents could not be loaded</strong><span>${escapeHtml(error.message)}</span></div>`}finally{$("#mediaLoading").hidden=true}}
$("#mediaFilters").addEventListener("click",event=>{const button=event.target.closest("button");if(!button)return;$$('#mediaFilters button').forEach(item=>item.classList.toggle("active",item===button));renderMedia()});["mediaSearch","mediaCategoryFilter","mediaSort"].forEach(id=>$("#"+id).addEventListener(id==="mediaSearch"?"input":"change",renderMedia));
$("#mediaFilterToggle").addEventListener("click",event=>{const expanded=event.currentTarget.getAttribute("aria-expanded")==="true";event.currentTarget.setAttribute("aria-expanded",String(!expanded));$("#mediaToolbar").classList.toggle("mobile-open",!expanded)});
$("#mediaViewOptions").addEventListener("click",event=>{const button=event.target.closest("button[data-layout]");if(!button)return;$$('#mediaViewOptions button').forEach(item=>item.classList.toggle("active",item===button));$("#mediaGrid").dataset.layout=button.dataset.layout;localStorage.setItem("oaMediaLayout",button.dataset.layout)});

let mediaPreviewUrl="";
function setMediaStep(preview){$("#mediaDetailsStep").hidden=preview;$("#mediaPreviewStep").hidden=!preview;$("#mediaBack").hidden=!preview;$("#mediaPreviewButton").hidden=preview;$("#mediaConfirm").hidden=!preview}
function openMediaModal(item=null){const form=$("#mediaForm");form.reset();form.dataset.editId=item?.id||"";$("#mediaModalTitle").textContent=item?"Edit Media or Document":"Add Media or Document";$("#mediaConfirm").textContent=item?"Save changes":"Confirm upload";$("#mediaCategory").innerHTML=categoryOptions(item?.category);$("#mediaFileHelp").textContent=item?"Optional: choose a file to replace the current one":"Required";if(item){Object.entries({title:item.title,assetType:item.assetType,description:item.description,labels:(item.labels||[]).join(", "),dateCreated:item.dateCreated,eventActivity:item.eventActivity,responsibleCommittee:item.responsibleCommittee,uploadedBy:item.uploadedBy,ownerContact:item.ownerContact,phone:item.phone,confidentiality:item.confidentiality,version:item.version,status:item.status,notes:item.notes}).forEach(([name,value])=>{const field=form.elements[name];if(field)field.value=value||""});form.elements.available.checked=Boolean(item.available)}setMediaStep(false);$("#mediaFormMessage").textContent="";$("#mediaModal").showModal()}
function closeMediaModal(){if(mediaPreviewUrl){URL.revokeObjectURL(mediaPreviewUrl);mediaPreviewUrl=""}$("#mediaModal").close()}
$("#addMedia").addEventListener("click",()=>openMediaModal());$("#closeMediaModal").addEventListener("click",closeMediaModal);$("#cancelMedia").addEventListener("click",closeMediaModal);$("#mediaBack").addEventListener("click",()=>setMediaStep(false));
$("#mediaPreviewButton").addEventListener("click",()=>{const form=$("#mediaForm"),file=form.elements.file.files[0];if(!form.reportValidity())return;if(!form.dataset.editId&&!file){$("#mediaFormMessage").textContent="Choose a file before continuing.";return}if(mediaPreviewUrl)URL.revokeObjectURL(mediaPreviewUrl);mediaPreviewUrl=file?URL.createObjectURL(file):"";const data=new FormData(form),existing=mediaFiles.find(item=>item.id===form.dataset.editId),previewHref=mediaPreviewUrl||existing?.previewHref;$("#mediaUploadPreview").innerHTML=`${previewHref&&((file?.type||existing?.mimeType||"").startsWith("image/"))?`<img src="${previewHref}" alt="Preview">`:`<div class="preview-file-icon">${escapeHtml((file?.name||existing?.originalName||"FILE").split(".").pop().toUpperCase())}</div>`}<dl><div><dt>Title</dt><dd>${escapeHtml(data.get("title"))}</dd></div><div><dt>Type</dt><dd>${escapeHtml(data.get("assetType"))}</dd></div><div><dt>Category</dt><dd>${escapeHtml(data.get("category"))}</dd></div><div><dt>File</dt><dd>${escapeHtml(file?.name||existing?.originalName||"")}</dd></div><div><dt>Description</dt><dd>${escapeHtml(data.get("description"))}</dd></div></dl>`;setMediaStep(true)});
$("#mediaForm").addEventListener("submit",async event=>{event.preventDefault();if(activeRole!=="admin")return;const form=event.currentTarget,button=$("#mediaConfirm"),formData=new FormData(form),editId=form.dataset.editId;formData.set("available",String(form.elements.available.checked));button.disabled=true;button.textContent=editId?"Saving…":"Uploading…";try{const payload=await apiJson(editId?`/api/media/${editId}/edit`:"/api/media",{method:"POST",body:formData});const index=mediaFiles.findIndex(item=>item.id===payload.item.id);if(index>=0)mediaFiles[index]=payload.item;else mediaFiles.unshift(payload.item);refreshCategoryFilter();renderMedia();closeMediaModal();toast(editId?"File details updated":"File uploaded and saved")}catch(error){console.error("media_save_failed",error);$("#mediaFormMessage").textContent=error.message;setMediaStep(false)}finally{button.disabled=false;button.textContent=editId?"Save changes":"Confirm upload"}});
$("#mediaGrid").addEventListener("click",async event=>{if(activeRole!=="admin")return;const edit=event.target.closest("[data-edit-media]");if(edit){openMediaModal(mediaFiles.find(item=>item.id===edit.dataset.editMedia));return}const remove=event.target.closest("[data-remove-media]");if(remove){const item=mediaFiles.find(file=>file.id===remove.dataset.removeMedia);if(!item||!confirm(`Remove "${item.title}"? This permanently deletes the file and its record.`))return;remove.disabled=true;try{await apiJson(`/api/media/${item.id}`,{method:"DELETE"});mediaFiles.splice(mediaFiles.indexOf(item),1);refreshCategoryFilter();renderMedia();toast("File removed")}catch(error){console.error("media_delete_failed",error);toast(error.message);remove.disabled=false}return}const toggle=event.target.closest("[data-toggle-media]");if(toggle){const item=mediaFiles.find(file=>file.id===toggle.dataset.toggleMedia),formData=new FormData();Object.entries({title:item.title,assetType:item.assetType,category:item.category,description:item.description,labels:(item.labels||[]).join(","),status:item.status,available:String(!item.available)}).forEach(([key,value])=>formData.append(key,value));try{const payload=await apiJson(`/api/media/${item.id}/edit`,{method:"POST",body:formData});Object.assign(item,payload.item);renderMedia();toast(item.available?"File shared with media partners":"File made private")}catch(error){console.error("media_access_update_failed",error);toast(error.message)}}});

function attachmentMarkup(file){const name=typeof file==="string"?file:file.name;const href=typeof file==="string"?"":file.href;return `<span class="attachment-item"><span class="attachment-chip" title="${escapeHtml(name)}">${escapeHtml(name)}</span>${href?`<a class="attachment-download" href="${href}" download="${escapeHtml(name)}">Download</a>`:""}${activeRole==="admin"&&file.id?`<button class="attachment-edit" type="button" data-edit-attachment="${file.id}">Edit</button><button class="attachment-remove" type="button" data-remove-attachment="${file.id}" data-file-name="${escapeHtml(name)}">Remove</button>`:""}</span>`}
function tributeUpdatedAt(party){return Math.max(Date.parse(party.createdAt||0)||0,...party.files.map(file=>Date.parse(file.uploadedAt||0)||0))}
function renderTributes(){const query=$("#tributeSearch").value.toLowerCase(),filter=$("#tributeStatusFilter").value;const visible=tributeParties.filter(p=>{const matches=filter==="all"||(filter==="outstanding"&&p.tribute!=="Received")||(filter==="not-recorded"&&(p.request==="Not recorded"||p.tribute==="Not recorded"))||(filter==="sent"&&p.request==="Sent")||(filter==="received"&&p.tribute==="Received");return matches&&`${p.name} ${p.phone}`.toLowerCase().includes(query)}).sort((a,b)=>tributeUpdatedAt(b)-tributeUpdatedAt(a)||b.id-a.id);$("#tributeTableBody").innerHTML=visible.map(p=>{const supporting=p.files.filter(file=>file.type!=="tribute"),tributes=p.files.filter(file=>file.type==="tribute");return `<tr><td>${escapeHtml(p.name)}</td><td>${p.phone?escapeHtml(p.phone):"<small>Not provided</small>"}</td><td><div class="attachment-list">${supporting.length?supporting.map(attachmentMarkup).join(""):"<small>No supporting files</small>"}</div></td><td><div class="attachment-list tribute-uploads">${tributes.length?tributes.map(attachmentMarkup).join(""):"<small>No tribute uploaded</small>"}</div></td><td><span class="status status-${slug(p.request)}">${p.request}</span></td><td><span class="status status-${slug(p.tribute)}">${p.tribute}</span></td><td><div class="tribute-upload-actions"><label class="tribute-file-label">+ Supporting file<input class="tribute-file-input" type="file" multiple data-upload-type="file" data-party-id="${p.id}" accept="image/*,.pdf,.doc,.docx"></label><label class="tribute-file-label tribute-upload-label">+ Tribute<input class="tribute-file-input" type="file" multiple data-upload-type="tribute" data-party-id="${p.id}" accept="image/*,.pdf,.doc,.docx"></label></div></td></tr>`}).join("")||`<tr><td colspan="7">No tribute records match this filter.</td></tr>`;renderStats()}
async function apiJson(url,options={}){const headers=new Headers(options.headers||{});headers.set("X-Teams-Role",activeRole);const response=await fetch(url,{cache:"no-store",...options,headers});let payload;try{payload=await response.json()}catch{throw new Error("Invalid server response ("+response.status+")")}if(!response.ok)throw new Error(payload.error||"Request failed ("+response.status+")");return payload}
async function syncTributes(){try{const [partyPayload,fileRecords]=await Promise.all([apiJson("/api/tributes/parties"),apiJson("/api/tributes/files")]);const parties=Array.isArray(partyPayload.parties)?partyPayload.parties:[];tributeParties.splice(0,tributeParties.length,...parties.map(party=>({...party,files:Array.isArray(fileRecords[String(party.id)])?fileRecords[String(party.id)]:[]})));renderTributes()}catch(error){console.error("tribute_sync_failed",error);toast("Tribute records could not be loaded. Please refresh and try again.")}}
$("#tributeSearch").addEventListener("input",renderTributes);$("#tributeStatusFilter").addEventListener("change",renderTributes);$("#tributeTableBody").addEventListener("change",async event=>{if(!event.target.matches(".tribute-file-input"))return;const input=event.target,party=tributeParties.find(p=>p.id===Number(input.dataset.partyId)),files=[...input.files],uploadType=input.dataset.uploadType||"file";if(!party||!files.length)return;input.disabled=true;toast(`Uploading ${uploadType==="tribute"?"tribute":"supporting file"}${files.length===1?"":"s"}...`);try{for(const file of files){const formData=new FormData();formData.append("file",file);formData.append("type",uploadType);await apiJson(`/api/tributes/${party.id}/files`,{method:"POST",body:formData})}await syncTributes();toast(`${uploadType==="tribute"?"Tribute":"Supporting files"} uploaded for ${party.name}`)}catch(error){console.error("tribute_upload_failed",error);toast(error.message||"Upload failed. Please try again.")}finally{input.disabled=false;input.value=""}});
$("#tributeTableBody").addEventListener("click",async event=>{
  if(activeRole!=="admin")return;
  const editButton=event.target.closest("[data-edit-attachment]");
  if(editButton){const attachment=tributeParties.flatMap(party=>party.files).find(file=>file.id===editButton.dataset.editAttachment);if(attachment)openModal("attachment",attachment);return}
  const removeButton=event.target.closest("[data-remove-attachment]");
  if(!removeButton||!confirm(`Remove "${removeButton.dataset.fileName}"? This cannot be undone.`))return;
  removeButton.disabled=true;
  try{
    const attachmentId=removeButton.dataset.removeAttachment;
    await apiJson(`/api/tributes/files/${attachmentId}`,{method:"DELETE"});
    await syncTributes();toast("Tribute document removed");
  }catch(error){console.error("tribute_delete_failed",error);toast(error.message||"The file could not be removed.");removeButton.disabled=false}
});

function option(value,current){return `<option${value===current?" selected":""}>${value}</option>`}
function activityGroupOptions(main,current){return subcommittees.filter(group=>group.mainCommittee===main&&group.active).map(group=>`<option value="${group.id}"${group.id===current?" selected":""}>${escapeHtml(group.name)}</option>`).join("")}
function openModal(type,item=null,viewOnly=false){const task=item||{task:"",mainCommittee:selectedCommittee==="brochure"?"brochure":"funeral",subcommitteeId:"",owner:"",supportingMembers:[],startDate:"",deadline:"",priority:"Normal",status:"not-started",progress:0,notes:"",labels:[]};const fields={task:`<label>Activity<input name="task" value="${escapeHtml(task.task)}" required></label><div class="form-grid"><label>Main committee<select name="mainCommittee" required><option value="funeral"${task.mainCommittee==="funeral"?" selected":""}>Funeral Committee</option><option value="brochure"${task.mainCommittee==="brochure"?" selected":""}>Brochure Committee</option></select></label><label>Subcommittee<select name="subcommitteeId" required>${activityGroupOptions(task.mainCommittee,task.subcommitteeId)}</select></label></div><div class="form-grid"><label>Person responsible<input name="owner" value="${escapeHtml(task.owner)}"></label><label>Supporting members <small>(comma-separated)</small><input name="supportingMembers" value="${escapeHtml((task.supportingMembers||[]).join(", "))}"></label><label>Start date<input name="startDate" type="date" value="${task.startDate||""}"></label><label>Deadline<input name="deadline" type="date" value="${task.deadline||""}"></label><label>Priority<select name="priority">${["Normal","High","Urgent"].map(value=>option(value,task.priority)).join("")}</select></label><label>Status<select name="status">${["not-started","in-progress","awaiting-feedback","blocked","nearing-completion","completed","overdue"].map(value=>`<option value="${value}"${value===task.status?" selected":""}>${statusText(value)}</option>`).join("")}</select></label><label>Progress<input name="progress" type="number" min="0" max="100" value="${task.progress}"></label><label>Labels <small>(comma-separated)</small><input name="labels" value="${escapeHtml((task.labels||[]).join(", "))}"></label></div><label>Notes<textarea name="notes">${escapeHtml(task.notes)}</textarea></label>`,party:`<label>Person or organisation<input name="party" required></label><label>Phone number<input name="phone" type="tel"></label>`,attachment:`<label>Upload type<select name="type"><option value="file"${item?.type!=="tribute"?" selected":""}>Supporting file</option><option value="tribute"${item?.type==="tribute"?" selected":""}>Tribute</option></select></label><label>Download name<input name="name" value="${escapeHtml(item?.name||"")}" required></label><label>Replace file <small>(optional)</small><input name="file" type="file" accept="image/*,.pdf,.doc,.docx"></label><p class="form-help">You can also move an upload between supporting files and tributes.</p>`,code:`<label>Role<select name="role"><option>Admin</option><option>Normal user</option><option>Media person</option></select></label><label>Internal label<input name="label" placeholder="Who is this code for?"></label>`};$("#recordForm").dataset.type=type;$("#recordForm").dataset.editId=item?String(item.id):"";$("#modalEyebrow").textContent=viewOnly?"Activity details":type==="code"?"Access control":type==="attachment"?"Tribute document":item?"Update record":"New record";$("#modalTitle").textContent=type==="task"?(viewOnly?"Activity":item?"Update activity":"Add activity"):type==="party"?"Add tribute party":type==="attachment"?"Edit uploaded document":"Generate access code";$("#modalSave").hidden=viewOnly;$("#modalSave").textContent=item?"Save changes":"Save";$("#modalFields").innerHTML=fields[type];if(type==="task")$("#modalFields [name=mainCommittee]").addEventListener("change",event=>{$("#modalFields [name=subcommitteeId]").innerHTML=activityGroupOptions(event.target.value,"")});if(viewOnly)$$("#modalFields input, #modalFields select, #modalFields textarea").forEach(control=>control.disabled=true);$("#recordModal").showModal()}
const taskCommitteeObserver=new MutationObserver(()=>{const main=$("#modalFields [name=mainCommittee]"),group=$("#modalFields [name=subcommitteeId]");if(!main||!group||main.querySelector('option[value="oko"]'))return;main.add(new Option("Logistics Uncle Oko","oko"));const editId=Number($("#recordForm").dataset.editId),record=tasks.find(item=>item.id===editId),desired=record?.mainCommittee||(selectedCommittee==="oko"?"oko":main.value);main.value=desired;group.innerHTML=activityGroupOptions(desired,record?.subcommitteeId||"")});
taskCommitteeObserver.observe($("#modalFields"),{childList:true});
$("#addTask").addEventListener("click",()=>openModal("task"));$("#addTributeParty").addEventListener("click",()=>openModal("party"));$("#generateCode").addEventListener("click",()=>openModal("code"));
async function activityAction(event){const share=event.target.closest("[data-share-task]");if(share){shareTask(tasks.find(item=>item.id===Number(share.dataset.shareTask)));return}if(activeRole!=="admin")return;const edit=event.target.closest("[data-edit-task]");if(edit){openModal("task",tasks.find(item=>item.id===Number(edit.dataset.editTask)));return}const remove=event.target.closest("[data-delete-task]");if(remove){const task=tasks.find(item=>item.id===Number(remove.dataset.deleteTask));if(task&&confirm(`Delete "${task.task}"?`)){await apiJson(`/api/activities/${task.id}`,{method:"DELETE"});tasks.splice(tasks.indexOf(task),1);renderTasks();renderCalendar();toast("Activity deleted")}return}const fileRemove=event.target.closest("[data-remove-activity-file]");if(fileRemove&&confirm("Remove this attachment?")){await apiJson(`/api/activities/files/${fileRemove.dataset.removeActivityFile}`,{method:"DELETE"});await syncActivities();toast("Attachment removed")}}
$("#taskTableBody").addEventListener("click",activityAction);$("#groupedActivities").addEventListener("click",activityAction);
$("#taskTableBody").addEventListener("change",async event=>{if(!event.target.matches("[data-activity-file]")||!event.target.files[0])return;const input=event.target,form=new FormData();form.append("file",input.files[0]);input.disabled=true;try{await apiJson(`/api/activities/${input.dataset.activityFile}/files`,{method:"POST",body:form});await syncActivities();toast("Attachment uploaded")}catch(error){toast(error.message)}finally{input.disabled=false}});
$("#recordForm").addEventListener("submit",async event=>{
  if(event.submitter?.value!=="save")return;
  event.preventDefault();
  const form=event.currentTarget,data=new FormData(form),type=form.dataset.type,saveButton=$("#modalSave");
  saveButton.disabled=true;
  try{
    if(type==="task"){
      const editId=Number(form.dataset.editId),values={task:data.get("task"),mainCommittee:data.get("mainCommittee"),subcommitteeId:data.get("subcommitteeId"),owner:data.get("owner"),supportingMembers:data.get("supportingMembers"),startDate:data.get("startDate"),deadline:data.get("deadline"),priority:data.get("priority"),status:data.get("status"),progress:data.get("progress"),labels:data.get("labels"),notes:data.get("notes")};
      const payload=await apiJson(editId?`/api/activities/${editId}`:"/api/activities",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(values)}),index=tasks.findIndex(record=>record.id===payload.task.id);
      if(index>=0)tasks[index]=payload.task;else tasks.push(payload.task);renderTasks();renderCalendar();toast(editId?"Activity updated":"Activity added");
    }else if(type==="party"){
      const payload=await apiJson("/api/tributes/parties",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:data.get("party").trim(),phone:data.get("phone").trim()})});
      tributeParties.push({...payload.party,files:[]});
      renderTributes();
      toast("Party saved to the tribute register");
    }else if(type==="attachment"){
      const attachmentId=form.dataset.editId,formData=new FormData();
      formData.append("name",data.get("name").trim());
      formData.append("type",data.get("type"));
      const replacement=data.get("file");if(replacement?.size)formData.append("file",replacement);
      await apiJson(`/api/tributes/files/${attachmentId}/edit`,{method:"POST",body:formData});
      await syncTributes();toast("Tribute document updated");
    }else{
      const code=`OA${Math.random().toString(36).slice(2,8).toUpperCase()}`;
      $("#codeList").insertAdjacentHTML("afterbegin",`<article><div><strong>${code}</strong><small>${escapeHtml(data.get("role"))} · ${escapeHtml(data.get("label")||"New code")}</small></div><span class="status active-status">Active</span></article>`);
      toast(`Access code ${code} generated`);
    }
    $("#recordModal").close();form.reset();form.dataset.editId="";
  }catch(error){
    console.error("record_save_failed",error);
    toast(error.message||"The record could not be saved.");
  }finally{saveButton.disabled=false}
});

